export function getDiaphragmPumpGuideCopy(locale: string, guide?: DiaphragmPumpGuide): Copy {
  const lang = normalizeDiaphragmPumpLocale(locale);
  const copy = copies[lang];
  if (!guide) return copy;
  return {
    ...copy,
    lifeNote: guide.gasLiquid ? seriesNotes[lang].gasLife : copy.lifeNote,
    mounting: guide.series === "DPL30" || guide.series === "DPL60" ? copy.mounting : seriesNotes[lang].mounting,
  };
}

