const nonCondensingSpec: Record<DiaphragmPumpPublicLocale, string> = {
  zh: "无冷凝", en: "non-condensing", es: "sin condensación",
  fr: "sans condensation", ko: "비응축", ru: "без конденсации",
};

/** Correct legacy presentation after localization. DPL30H connections: A00 p.5.
 * Keep table aliases, material notation and breadcrumb language consistent.
 */
export function applyDiaphragmPumpGuideSpecs<T extends Record<string, unknown>>(data: T, locale: string): T {
  const guide = getDiaphragmPumpGuide(String(data.slug || ""));
  if (!guide) return data;
  const lang = normalizeDiaphragmPumpLocale(locale);
  const connection = dpl30hConnectionSpec[lang];
  const rows = (items: unknown) => Array.isArray(items) ? items.map(item => {
    if (!item || typeof item !== "object") return item;
    const row = item as Record<string, unknown>;
    const original = String(row.value || row.content || "");
    const value = guide.highPressure && /6\s*[×x*]\s*4/i.test(original) ? connection : original
      .replace(/\bPP\s+S\b/g, "PPS")
      .replace(/Nonn?-Condensing/gi, nonCondensingSpec[lang]);
    if (value === original) return item;
    return { ...row, value, ...(row.content !== undefined ? { content: value } : {}) };
  }) : items;
  const patch: Record<string, unknown> = {};
  for (const key of ["specs", "specifications", "specList", "technicalSpecifications"]) {
    if (Array.isArray(data[key])) patch[key] = rows(data[key]);
  }
  if (Array.isArray(data.specGroups)) {
    patch.specGroups = data.specGroups.map(group => ({ ...group, items: rows(group.items) }));
  }
  if (Array.isArray(data.breadcrumbs)) {
    patch.breadcrumbs = data.breadcrumbs.map(item => ({ ...item,
      ...(typeof item.label === "string" ? { label: diaphragmText(item.label, locale) } : {}),
      ...(typeof item.href === "string" ? { href: diaphragmHref(item.href, locale) } : {}),
    }));
  }
  return { ...data, ...patch };
}
